package com.library.ui; import com.library.model.*; import com.library.service.*; import javax.swing.*; import java.awt.*; import java.util.*;
public class IssueBookFrame extends JFrame { private final JComboBox<Member> members=new JComboBox<>();private final JComboBox<Book> books=new JComboBox<>();private final JTextField studentSearch=new JTextField(),bookSearch=new JTextField();private final JSpinner duration=new JSpinner(new SpinnerNumberModel(14,1,30,1)); private java.util.List<Member> allMembers=java.util.List.of(); public IssueBookFrame(){super("Issue Book");setSize(760,490);setMinimumSize(new Dimension(650,420));setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout());root.add(UI.header(this,"Issue Book","Search student/book and enter any loan duration from 1 to 30 days"),BorderLayout.NORTH);JPanel p=new JPanel(new GridBagLayout());p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createEmptyBorder(24,32,24,32));GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(8,8,8,8);c.fill=GridBagConstraints.HORIZONTAL;c.weightx=1;add(p,c,0,"Search student (enrollment, email, phone or name)",studentSearch);JButton findStudent=UI.button("Find student");findStudent.addActionListener(e->filterMembers());c.gridx=2;c.gridy=0;c.weightx=0;p.add(findStudent,c);add(p,c,1,"Select student",members);add(p,c,2,"Search book (name or ID)",bookSearch);JButton findBook=UI.button("Find book");findBook.addActionListener(e->filterBooks());c.gridx=2;c.gridy=2;c.weightx=0;p.add(findBook,c);add(p,c,3,"Select available book",books);add(p,c,4,"Loan duration (days, 1–30)",duration);JButton issue=UI.button("Issue Selected Book");issue.addActionListener(e->issue());c.gridx=1;c.gridy=5;c.gridwidth=2;p.add(issue,c);root.add(p);add(root);load();} private void add(JPanel p,GridBagConstraints c,int row,String label,JComponent field){c.gridwidth=1;c.weightx=0;c.gridx=0;c.gridy=row;p.add(new JLabel(label),c);c.gridx=1;c.weightx=1;p.add(field,c);} private void load(){try{allMembers=new MemberService().activeMembers();filterMembers();filterBooks();}catch(Exception e){UI.error(this,e);}} private void filterMembers(){members.removeAllItems();String q=studentSearch.getText().trim().toLowerCase();for(Member m:allMembers)if(q.isEmpty()||String.valueOf(m.getMemberId()).contains(q)||m.getName().toLowerCase().contains(q)||m.getEmail().toLowerCase().contains(q)||m.getPhone().contains(q))members.addItem(m);} private void filterBooks(){books.removeAllItems();for(Book b:new BookService().search(bookSearch.getText()))if("ACTIVE".equals(b.getStatus())&&b.getAvailableQuantity()>0)books.addItem(b);} private void issue(){try{Member m=(Member)members.getSelectedItem();Book b=(Book)books.getSelectedItem();int days=(Integer)duration.getValue();if(m==null||b==null)throw new IllegalArgumentException("Find and select a student and book.");new LibraryService().issue(m.getMemberId(),b.getBookId(),days);UI.info(this,"Book issued successfully. Due date: "+java.time.LocalDate.now().plusDays(days));load();}catch(Exception e){UI.error(this,e);}} }
